import{_ as a,C as r,o,c as n,a6 as d,E as s}from"./chunks/framework.BJFjZBwW.js";const f=JSON.parse('{"title":"Boards","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"prerequisites/board.md","filePath":"prerequisites/board.md","lastUpdated":1785770623000}'),i={name:"prerequisites/board.md"};function l(h,e,c,p,b,u){const t=r("BoardEnvironmentTable");return o(),n("div",null,[e[0]||(e[0]=d('<h1 id="boards" tabindex="-1">Boards <a class="header-anchor" href="#boards" aria-label="Permalink to &quot;Boards&quot;">​</a></h1><p>OpenMQTTGateway is not closed to one board or type of board, by using the power of the Arduino framework and libraries that are cross compatibles it let you many choice of hardware, from an ESP8266 to an ESP32.</p><h2 id="which-board-do-i-need" tabindex="-1">Which board do I need? <a class="header-anchor" href="#which-board-do-i-need" aria-label="Permalink to &quot;Which board do I need?&quot;">​</a></h2><p>For the most common use cases, the choice is simple:</p><table tabindex="0"><thead><tr><th>I want to...</th><th>Recommended board</th><th style="text-align:center;">Extra hardware</th></tr></thead><tbody><tr><td>Bring Bluetooth sensors into my home automation</td><td>Any ESP32 development board</td><td style="text-align:center;">None</td></tr><tr><td>Receive RF devices — 433/315/868/915MHz (weather stations, door/PIR sensors...)</td><td>LILYGO® LoRa32 V2.1 or Heltec LoRa V2, matching your devices&#39; frequency</td><td style="text-align:center;">None</td></tr><tr><td>Send and receive RF remotes and switches (433/315MHz)</td><td>ESP32 + SRX882/STX882 or CC1101 modules</td><td style="text-align:center;"><a href="./../setitup/rf.html">Wiring</a></td></tr><tr><td>Control my TV or AC through infrared</td><td>ESP32 + IR emitter/receiver</td><td style="text-align:center;"><a href="./../setitup/ir.html">Wiring</a></td></tr><tr><td>Reach far-away sensors with LoRa</td><td>LILYGO® LoRa32 or Heltec LoRa board</td><td style="text-align:center;">None</td></tr><tr><td>Skip flashing and wiring entirely</td><td><a href="https://shop.theengs.io/" target="_blank" rel="noreferrer">Theengs Bridge</a>, a pre-flashed BLE gateway</td><td style="text-align:center;">None</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Running on a computer</p><p>If you want to use the BLE decoding capabilities of OpenMQTTGateway with a Raspberry Pi, Windows or Unix PC you can use <a href="https://gateway.theengs.io/" target="_blank" rel="noreferrer">Theengs Gateway</a>, and on a tablet or smartphone the <a href="https://app.theengs.io/" target="_blank" rel="noreferrer">Theengs App</a>.</p></div><h2 id="exploring-further" tabindex="-1">Exploring further <a class="header-anchor" href="#exploring-further" aria-label="Permalink to &quot;Exploring further&quot;">​</a></h2><p>Moreover the gateways capacities can be extended with sensors; DHT, HC SR501, ADC, I2C bus, INA226, MQ2, TEMT6000, TSL2561, BME280/BMP280, HTU21D, AHTx0, DS1820 or actuators; LED, relays, PWM.</p><p>Choosing your board depends heavily on the technologies you want to use with it. The choice between these boards will depend on your knowledge and your requirements in terms of reliability, situation, modules wanted and devices you already have. Use the table below to explore the latest environments.</p>',9)),s(t,{boardsUrl:"/boards-info.json",selectorPath:"/upload/board-selector.html"})])}const g=a(i,[["render",l]]);export{f as __pageData,g as default};
